insert into public.interview_questions (role_category, round, difficulty, question, expected_keywords, rubric, model_answer)
values
  ('Software & Web', 'Behavioral', 'Junior', 'Tell me about a feature you delivered from a user need through release. What did you build, how did you validate it, and what changed for users?', array['acceptance criteria', 'api contract', 'tests', 'user outcome']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would explain the user problem, the contract I agreed with the API owner, the tests I added, and the user-visible result.'),
  ('Software & Web', 'Technical', 'Mid', 'A request can be retried after a timeout and may update several related records. How would you make the operation safe?', array['idempotency', 'transaction', 'authorization', 'constraints']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would validate and authorize the request, use an idempotency key, and commit related writes in one transaction protected by constraints.'),
  ('Software & Web', 'System Design', 'Senior', 'Design a service change that can be released gradually and rolled back if an important user journey degrades.', array['service objective', 'telemetry', 'canary', 'rollback']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would define a user-facing service objective, add request and outcome telemetry, release to a small canary, and roll back automatically when guardrails fail.'),
  ('AI & Data Science', 'Behavioral', 'Junior', 'Tell me about a time data quality changed your analysis or model result. How did you discover and address it?', array['provenance', 'missing values', 'validation', 'baseline']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would describe the source and label assumptions, quantify missing or invalid values, validate a correction, and compare results with a baseline.'),
  ('AI & Data Science', 'Technical', 'Mid', 'How would you evaluate a model when records from the same person or time period could appear in both training and test data?', array['data leakage', 'group split', 'time split', 'holdout']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would split by the independent entity or time boundary before fitting transformations and preserve a final holdout for unbiased evaluation.'),
  ('AI & Data Science', 'System Design', 'Senior', 'Design monitoring for a deployed prediction pipeline where input data and user outcomes can drift.', array['data drift', 'outcome quality', 'privacy', 'fallback']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would monitor input distributions and delayed outcomes, minimize sensitive logging, define alert thresholds, and provide a safe fallback when quality degrades.'),
  ('Cloud & DevOps', 'Behavioral', 'Junior', 'Tell me about a deployment or environment issue you helped resolve. How did you identify the cause and verify recovery?', array['logs', 'health check', 'root cause', 'recovery']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would describe the symptom, the logs or health checks that isolated it, the change made, and the evidence that service recovered.'),
  ('Cloud & DevOps', 'Technical', 'Mid', 'How would you provision the same service consistently across development, staging, and production?', array['infrastructure as code', 'least privilege', 'secrets', 'review']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would use reviewed infrastructure definitions, environment-specific configuration, least-privilege identities, and managed secrets.'),
  ('Cloud & DevOps', 'System Design', 'Senior', 'Design a reliability plan for a service that depends on a regional cloud service and has a strict recovery target.', array['service level objective', 'failure domain', 'recovery time', 'failover']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would define user-facing objectives, map failure domains, test recovery against the target, and keep failover and data recovery procedures observable.'),
  ('Cybersecurity', 'Behavioral', 'Junior', 'Tell me about a security risk you found during development or testing. How did you report it and confirm it was addressed?', array['scope', 'evidence', 'impact', 'retest']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would describe the authorized scope, preserve minimal reproducible evidence, explain impact, and retest the approved fix.'),
  ('Cybersecurity', 'Technical', 'Mid', 'How would you investigate a report that one user can access another user''s record by changing an identifier?', array['authorization', 'ownership', 'server side', 'negative test']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would reproduce the issue in scope, trace server-side ownership checks, add authorization at the data boundary, and test both allowed and denied users.'),
  ('Cybersecurity', 'System Design', 'Senior', 'Plan the first response to a confirmed credential exposure affecting a production service.', array['containment', 'revoke credentials', 'preserve evidence', 'rotate']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would contain access, revoke and rotate affected credentials, preserve relevant evidence, assess access scope, and coordinate recovery and notification owners.'),
  ('Mobile & Multiplatform', 'Behavioral', 'Junior', 'Tell me about a mobile feature that had to work across different device or network conditions. What did you test?', array['lifecycle', 'offline', 'device matrix', 'accessibility']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would explain the lifecycle and connectivity cases, the representative devices tested, and how I verified accessible recovery when a request failed.'),
  ('Mobile & Multiplatform', 'Technical', 'Mid', 'How would you preserve a user''s in-progress task when a mobile app is backgrounded or recreated?', array['persisted state', 'lifecycle', 'restore', 'privacy']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would persist only the state needed to resume, restore it through lifecycle transitions, and avoid storing sensitive values without a clear need.'),
  ('Mobile & Multiplatform', 'System Design', 'Senior', 'Design a staged mobile release for a change that touches permissions, local data, and a shared backend.', array['permission review', 'compatibility', 'crash monitoring', 'rollback']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would review permissions and data migration, validate supported versions, stage the rollout, monitor crashes and backend outcomes, and define rollback or recovery.'),
  ('Game Dev & 3D', 'Behavioral', 'Junior', 'Tell me about a gameplay or 3D interaction you improved after observing people use it. What evidence changed your design?', array['playtest', 'feedback', 'iteration', 'player outcome']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would describe the observed friction, the change made, a follow-up playtest, and the behavior that improved.'),
  ('Game Dev & 3D', 'Technical', 'Mid', 'How would you investigate intermittent frame-time spikes in a scene that performs well on your workstation?', array['target hardware', 'profiling', 'frame time', 'memory']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would profile a representative scene on target hardware, compare frame-time traces and memory use, then change the measured bottleneck and retest.'),
  ('Game Dev & 3D', 'System Design', 'Senior', 'Design deterministic replay or save behavior for a game feature that must survive updates across platforms.', array['state version', 'determinism', 'compatibility', 'migration']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would version the serialized state, define deterministic inputs and update rules, test compatibility across supported platforms, and provide a migration or recovery path.'),
  ('UI/UX & Product Design', 'Behavioral', 'Junior', 'Tell me about a design decision you changed after user research or usability testing. What did you observe?', array['user task', 'research evidence', 'prototype', 'iteration']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would state the user task, what participants did rather than only said, the prototype change, and the follow-up evidence.'),
  ('UI/UX & Product Design', 'Technical', 'Mid', 'How would you make a complex form usable for keyboard and assistive-technology users?', array['labels', 'keyboard', 'focus', 'error identification']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would use semantic controls and labels, test the full keyboard path and visible focus, and connect each validation error to its field.'),
  ('UI/UX & Product Design', 'System Design', 'Senior', 'How would you evolve a design system while keeping established product flows consistent and accessible?', array['design tokens', 'component states', 'accessibility', 'adoption']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would define token and component changes, audit interaction states against accessibility criteria, document migration guidance, and measure adoption with product teams.'),
  ('Product & Agile Leadership', 'Behavioral', 'Junior', 'Tell me about a time you helped a team clarify an unclear request. How did you agree on the user outcome?', array['user problem', 'acceptance criteria', 'stakeholders', 'outcome']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would explain how I aligned stakeholders on the user problem, wrote observable acceptance criteria, and checked the delivered outcome.'),
  ('Product & Agile Leadership', 'Technical', 'Mid', 'How would you prioritize two requests when one has strong user evidence and the other has a senior sponsor?', array['evidence', 'impact', 'risk', 'opportunity cost']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would compare user impact, evidence, risk, effort, and opportunity cost against shared goals, then communicate the decision and its tradeoffs.'),
  ('Product & Agile Leadership', 'System Design', 'Senior', 'How would you evaluate a product experiment that improves conversion but worsens a user-protection metric?', array['hypothesis', 'guardrail metric', 'decision rule', 'user impact']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would use the pre-agreed guardrail and decision rule, investigate affected cohorts, and stop or adjust the experiment if the user harm exceeds the acceptable threshold.'),
  ('QA & Reliability', 'Behavioral', 'Junior', 'Tell me about a defect you helped prevent or detect before release. How did you reproduce and communicate it?', array['reproduction steps', 'severity', 'evidence', 'regression']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would give reproducible steps, describe impact and evidence, coordinate the fix, and add a regression check.'),
  ('QA & Reliability', 'Technical', 'Mid', 'How would you diagnose a flaky automated test that intermittently fails in CI but passes locally?', array['shared state', 'timing', 'environment', 'deterministic']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would compare environment and timing, isolate shared state or order dependencies, and remove nondeterminism instead of hiding failures with retries.'),
  ('QA & Reliability', 'System Design', 'Senior', 'Design release-quality signals for a critical user workflow that spans several services.', array['risk based', 'service indicators', 'failure injection', 'rollback']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would map critical risks to test levels, monitor end-to-end user indicators, exercise dependency failures, and define release and rollback thresholds.'),
  ('FinTech & Web3', 'Behavioral', 'Junior', 'Tell me about a time you found a discrepancy between a transaction record and a reported balance. How did you investigate?', array['reconciliation', 'event history', 'precision', 'audit trail']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would compare source events with the reported balance, preserve an attributable audit trail, check currency and precision rules, and explain the discrepancy.'),
  ('FinTech & Web3', 'Technical', 'Mid', 'How would you prevent a retry after a payment timeout from charging a customer twice?', array['idempotency key', 'operation status', 'transaction', 'duplicate']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would bind an idempotency key to the logical operation, store its outcome atomically, and return that outcome for a safe retry.'),
  ('FinTech & Web3', 'System Design', 'Senior', 'Design controls for a high-risk financial adjustment that must be traceable and recoverable.', array['separation of duties', 'append only', 'approval', 'reconciliation']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would require scoped authorization and independent approval, append attributable events, reconcile the ledger, and document reversal and incident procedures.'),
  ('Hardware & Robotics', 'Behavioral', 'Junior', 'Tell me about an intermittent hardware or sensor failure you investigated. What measurements helped isolate it?', array['controlled conditions', 'calibration', 'measurements', 'reproduction']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would reproduce the issue under controlled conditions, check calibration, capture power and interface measurements, and record the successful fix and retest.'),
  ('Hardware & Robotics', 'Technical', 'Mid', 'How would you validate a sensor''s accuracy across its specified operating range?', array['reference instrument', 'tolerance', 'environment', 'calibration']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would compare against a calibrated reference across defined environmental points and document uncertainty and tolerance limits.'),
  ('Hardware & Robotics', 'System Design', 'Senior', 'Design a safe production test and service process for a connected device with firmware and moving components.', array['safety limits', 'firmware version', 'diagnostics', 'traceability']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would define safety interlocks, trace hardware and firmware revisions, capture diagnostic results, and document service and rollback procedures.'),
  ('Enterprise & Applied Tech', 'Behavioral', 'Junior', 'Tell me about a time you aligned people from different teams before changing a shared workflow.', array['stakeholders', 'current process', 'decision owner', 'communication']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would map the current process, clarify each stakeholder''s outcome and decision rights, and confirm the change and support plan before rollout.'),
  ('Enterprise & Applied Tech', 'Technical', 'Mid', 'How would you integrate two enterprise systems when ownership and data formats differ?', array['versioned contract', 'data ownership', 'validation', 'failure handling']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would agree on a versioned contract and field ownership, validate both sides, and make partial failures observable and recoverable.'),
  ('Enterprise & Applied Tech', 'System Design', 'Senior', 'Plan a rollout that migrates business-critical records while keeping teams operational.', array['pilot', 'reconciliation', 'support readiness', 'rollback']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I would pilot with affected users, validate and reconcile migrated records, train support, stage the cutover, and define rollback and ownership.')
