-- Role-category interview prompts for the curated career catalog.
-- Automated keyword/STAR scores are practice signals, not hiring predictions.
alter table public.interview_questions
  add column role_category text check (role_category in ('Software & Web', 'AI & Data Science', 'Cloud & DevOps', 'Cybersecurity', 'Mobile & Multiplatform', 'Game Dev & 3D', 'UI/UX & Product Design', 'Product & Agile Leadership', 'QA & Reliability', 'FinTech & Web3', 'Hardware & Robotics', 'Enterprise & Applied Tech'));

create index interview_questions_category_created_idx
  on public.interview_questions (role_category, created_at, id)
  where role_category is not null;
create unique index interview_questions_category_question_idx
  on public.interview_questions (role_category, question)
  where role_category is not null;

-- Existing bundled questions are software engineering practice prompts.
update public.interview_questions as question
set role_category = 'Software & Web'
from public.roles as role
where question.role_id = role.id
  and role.slug = 'frontend-developer'
  and question.role_category is null;

on conflict (role_category, question) where role_category is not null do nothing;
